'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useSiteSettings } from '@/context/SiteContext';
import { FiMail, FiLock, FiEye, FiEyeOff, FiCheckCircle, FiAlertCircle, FiArrowLeft } from 'react-icons/fi';
import { useRouter } from 'next/navigation';

export default function ForgotPasswordPage() {
    const { settings, loading: settingsLoading } = useSiteSettings();
    const router = useRouter();
    const [step, setStep] = useState<1 | 2>(1);

    // Form states
    const [email, setEmail] = useState('');
    const [otp, setOtp] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');

    // UI states
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [successMessage, setSuccessMessage] = useState('');

    const handleRequestOtp = async (e: React.FormEvent) => {
        e.preventDefault();

        if (!settings.emailEnabled) {
            setError('Password reset is currently disabled. Please contact support.');
            return;
        }

        setIsLoading(true);
        setError('');
        setSuccessMessage('');

        try {
            const response = await fetch('/api/auth/forgot-password', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email }),
            });

            const data = await response.json();

            if (data.success) {
                setSuccessMessage(data.message);
                setStep(2);
            } else {
                setError(data.message || 'Failed to send OTP');
            }
        } catch (error) {
            setError('An error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleResetPassword = async (e: React.FormEvent) => {
        e.preventDefault();

        if (password !== confirmPassword) {
            setError('Passwords do not match');
            return;
        }

        setIsLoading(true);
        setError('');
        setSuccessMessage('');

        try {
            const response = await fetch('/api/auth/reset-password', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email, otp, newPassword: password }),
            });

            const data = await response.json();

            if (data.success) {
                setSuccessMessage('Password reset successfully! Redirecting to login...');
                setTimeout(() => {
                    router.push('/login');
                }, 2000);
            } else {
                setError(data.message || 'Failed to reset password');
            }
        } catch (error) {
            setError('An error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background-dark via-primary-950 to-background-dark relative overflow-hidden">
            {/* Background Elements */}
            <div className="absolute top-0 right-0 w-96 h-96 bg-accent-gold/10 rounded-full blur-3xl" />
            <div className="absolute bottom-0 left-0 w-96 h-96 bg-accent-emerald/10 rounded-full blur-3xl" />

            <div className="section-container relative z-10 py-12">
                <div className="max-w-md mx-auto">
                    {/* Logo */}
                    <Link href="/" className="flex items-center justify-center space-x-2 mb-8">
                        {settings.siteLogo ? (
                            <img src={settings.siteLogo} alt={settings.siteName} className="h-12 w-auto object-contain" />
                        ) : (
                            <div className="w-12 h-12 bg-gradient-to-br from-accent-gold to-accent-gold-dark rounded-xl flex items-center justify-center">
                                <span className="text-primary-950 font-bold text-2xl font-serif">{settings.siteName.charAt(0)}</span>
                            </div>
                        )}
                    </Link>

                    {/* Card */}
                    <div className="card-premium">
                        <div className="text-center mb-8">
                            <h1 className="text-3xl font-bold font-serif text-white mb-2">
                                {step === 1 ? 'Forgot Password' : 'Reset Password'}
                            </h1>
                            <p className="text-gray-400">
                                {step === 1
                                    ? 'Enter your email to receive a verification code'
                                    : 'Enter the code sent to your email and your new password'}
                            </p>
                        </div>

                        {/* Error Message */}
                        {error && (
                            <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-lg flex items-center space-x-3">
                                <FiAlertCircle className="w-5 h-5 text-red-400 flex-shrink-0" />
                                <p className="text-red-300 text-sm">{error}</p>
                            </div>
                        )}

                        {/* Success Message */}
                        {successMessage && (
                            <div className="mb-6 p-4 bg-green-500/10 border border-green-500/30 rounded-lg flex items-center space-x-3">
                                <FiCheckCircle className="w-5 h-5 text-green-400 flex-shrink-0" />
                                <p className="text-green-300 text-sm">{successMessage}</p>
                            </div>
                        )}

                        {/* Warning if Email Disabled */}
                        {!settingsLoading && !settings.emailEnabled && step === 1 && (
                            <div className="mb-6 p-4 bg-yellow-500/10 border border-yellow-500/30 rounded-lg flex items-center space-x-3">
                                <FiAlertCircle className="w-5 h-5 text-yellow-500 flex-shrink-0" />
                                <p className="text-yellow-200 text-sm">Password reset is currently unavailable. Please contact support.</p>
                            </div>
                        )}

                        {step === 1 ? (
                            <form onSubmit={handleRequestOtp} className="space-y-6">
                                <div>
                                    <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-2">
                                        Email Address
                                    </label>
                                    <div className="relative">
                                        <FiMail className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="email"
                                            type="email"
                                            value={email}
                                            onChange={(e) => setEmail(e.target.value)}
                                            placeholder="you@example.com"
                                            className="input-premium pl-12"
                                            required
                                        />
                                    </div>
                                </div>
                                <button
                                    type="submit"
                                    disabled={isLoading || !settings.emailEnabled}
                                    className="btn-primary w-full text-lg disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    {isLoading ? 'Sending OTP...' : 'Send OTP'}
                                </button>
                            </form>
                        ) : (
                            <form onSubmit={handleResetPassword} className="space-y-6">
                                {/* OTP */}
                                <div>
                                    <label htmlFor="otp" className="block text-sm font-medium text-gray-300 mb-2">
                                        Verification Code (OTP)
                                    </label>
                                    <input
                                        id="otp"
                                        type="text"
                                        value={otp}
                                        onChange={(e) => setOtp(e.target.value)}
                                        placeholder="Enter 6-digit code"
                                        className="input-premium text-center tracking-widest text-lg"
                                        required
                                        maxLength={6}
                                    />
                                </div>

                                {/* Password */}
                                <div>
                                    <label htmlFor="password" className="block text-sm font-medium text-gray-300 mb-2">
                                        New Password
                                    </label>
                                    <div className="relative">
                                        <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="password"
                                            type={showPassword ? 'text' : 'password'}
                                            value={password}
                                            onChange={(e) => setPassword(e.target.value)}
                                            placeholder="••••••••"
                                            className="input-premium pl-12 pr-12"
                                            required
                                            minLength={6}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setShowPassword(!showPassword)}
                                            className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                        >
                                            {showPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                        </button>
                                    </div>
                                </div>

                                {/* Confirm Password */}
                                <div>
                                    <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-300 mb-2">
                                        Confirm New Password
                                    </label>
                                    <div className="relative">
                                        <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="confirmPassword"
                                            type={showConfirmPassword ? 'text' : 'password'}
                                            value={confirmPassword}
                                            onChange={(e) => setConfirmPassword(e.target.value)}
                                            placeholder="••••••••"
                                            className="input-premium pl-12 pr-12"
                                            required
                                            minLength={6}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                            className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                        >
                                            {showConfirmPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                        </button>
                                    </div>
                                </div>

                                <button
                                    type="submit"
                                    disabled={isLoading}
                                    className="btn-primary w-full text-lg disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    {isLoading ? 'Resetting Password...' : 'Reset Password'}
                                </button>

                                <div className="text-center mt-4">
                                    <button
                                        type="button"
                                        onClick={() => setStep(1)}
                                        className="text-sm text-gray-400 hover:text-accent-gold transition-colors"
                                    >
                                        Change Email / Resend Code
                                    </button>
                                </div>
                            </form>
                        )}
                    </div>

                    {/* Back to Login */}
                    <div className="text-center mt-6">
                        <Link href="/login" className="text-gray-400 hover:text-accent-gold transition-colors text-sm flex items-center justify-center space-x-2">
                            <FiArrowLeft className="w-4 h-4" />
                            <span>Back to Login</span>
                        </Link>
                    </div>
                </div>
            </div>
        </main>
    );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useSiteSettings } from '@/context/SiteContext';
import { FiMail, FiLock, FiEye, FiEyeOff, FiShield, FiAlertCircle } from 'react-icons/fi';

export default function LoginPage() {
    const { settings } = useSiteSettings();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        try {
            const response = await fetch('/api/auth/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ email, password }),
            });

            const data = await response.json();

            if (data.success) {
                // Store user data in localStorage (in production, use secure session/JWT)
                localStorage.setItem('user', JSON.stringify(data.user));

                // Redirect based on user role
                window.location.href = data.redirectTo;
            } else {
                setError(data.message || 'Login failed');
            }
        } catch (error) {
            console.error('Login error:', error);
            setError('An error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background-dark via-primary-950 to-background-dark relative overflow-hidden">
            {/* Background Elements */}
            <div className="absolute top-0 right-0 w-96 h-96 bg-accent-gold/10 rounded-full blur-3xl" />
            <div className="absolute bottom-0 left-0 w-96 h-96 bg-accent-emerald/10 rounded-full blur-3xl" />

            <div className="section-container relative z-10 py-12">
                <div className="max-w-md mx-auto">
                    {/* Logo */}
                    <Link href="/" className="flex items-center justify-center space-x-2 mb-8">
                        {settings.siteLogo ? (
                            <img src={settings.siteLogo} alt={settings.siteName} className="h-12 w-auto object-contain" />
                        ) : (
                            <div className="w-12 h-12 bg-gradient-to-br from-accent-gold to-accent-gold-dark rounded-xl flex items-center justify-center">
                                <span className="text-primary-950 font-bold text-2xl font-serif">{settings.siteName.charAt(0)}</span>
                            </div>
                        )}
                        <span className="text-2xl font-serif font-bold gradient-text">
                            {settings.siteName}
                        </span>
                    </Link>

                    {/* Login Card */}
                    <div className="card-premium">
                        <div className="text-center mb-8">
                            <h1 className="text-3xl font-bold font-serif text-white mb-2">Welcome Back</h1>
                            <p className="text-gray-400">Sign in to access your investment portfolio</p>
                        </div>

                        {/* Error Message */}
                        {error && (
                            <div className="mb-6 p-4 bg-red-500/10 border border-red-500/30 rounded-lg flex items-center space-x-3">
                                <FiAlertCircle className="w-5 h-5 text-red-400 flex-shrink-0" />
                                <p className="text-red-300 text-sm">{error}</p>
                            </div>
                        )}

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {/* Email */}
                            <div>
                                <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-2">
                                    Email Address
                                </label>
                                <div className="relative">
                                    <FiMail className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="email"
                                        type="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        placeholder="you@example.com"
                                        className="input-premium pl-12"
                                        required
                                    />
                                </div>
                            </div>

                            {/* Password */}
                            <div>
                                <label htmlFor="password" className="block text-sm font-medium text-gray-300 mb-2">
                                    Password
                                </label>
                                <div className="relative">
                                    <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="password"
                                        type={showPassword ? 'text' : 'password'}
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        placeholder="••••••••"
                                        className="input-premium pl-12 pr-12"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                    >
                                        {showPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                    </button>
                                </div>
                            </div>

                            {/* Forgot Password */}
                            <div className="flex items-center justify-between">
                                <label className="flex items-center space-x-2 cursor-pointer">
                                    <input type="checkbox" className="w-4 h-4 rounded border-primary-700 bg-primary-800 text-accent-gold focus:ring-accent-gold/50" />
                                    <span className="text-sm text-gray-400">Remember me</span>
                                </label>
                                <Link href="/forgot-password" className="text-sm text-accent-gold hover:text-accent-gold-light transition-colors">
                                    Forgot password?
                                </Link>
                            </div>

                            {/* Submit Button */}
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="btn-primary w-full text-lg disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isLoading ? 'Signing in...' : 'Sign In'}
                            </button>
                        </form>

                        {/* Divider */}
                        <div className="relative my-8">
                            <div className="divider" />
                            <span className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-background-dark-secondary px-4 text-sm text-gray-400">
                                or
                            </span>
                        </div>

                        {/* Sign Up Link */}
                        <p className="text-center text-gray-400">
                            Don't have an account?{' '}
                            <Link href="/register" className="text-accent-gold hover:text-accent-gold-light font-semibold transition-colors">
                                Create Account
                            </Link>
                        </p>

                        {/* Trust Indicators */}
                        <div className="mt-8 pt-6 border-t border-primary-700/30">
                            <div className="flex items-center justify-center space-x-2 text-sm text-gray-400">
                                <FiShield className="w-4 h-4 text-accent-emerald" />
                                <span>Secure login with 256-bit encryption</span>
                            </div>
                        </div>
                    </div>

                    {/* Back to Home */}
                    <div className="text-center mt-6">
                        <Link href="/" className="text-gray-400 hover:text-accent-gold transition-colors text-sm">
                            ← Back to Home
                        </Link>
                    </div>
                </div>
            </div>
        </main>
    );
}

'use client';

import { useState } from 'react';
import Link from 'next/link';
import { useSiteSettings } from '@/context/SiteContext';
import { FiMail, FiLock, FiEye, FiEyeOff, FiUser, FiPhone, FiShield, FiCheckCircle, FiGlobe } from 'react-icons/fi';
import { countries } from '@/lib/countries';

export default function RegisterPage() {
    const { settings } = useSiteSettings();
    const [formData, setFormData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        country: '',
        phoneCode: '',
        phone: '',
        password: '',
        confirmPassword: '',
    });
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [agreedToTerms, setAgreedToTerms] = useState(false);
    const [isLoading, setIsLoading] = useState(false);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleCountryChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        const selectedCountry = countries.find(c => c.name === e.target.value);
        setFormData({
            ...formData,
            country: e.target.value,
            phoneCode: selectedCountry?.phoneCode || ''
        });
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        if (formData.password !== formData.confirmPassword) {
            alert('Passwords do not match');
            return;
        }

        if (!agreedToTerms) {
            alert('Please agree to the terms and conditions');
            return;
        }

        setIsLoading(true);

        try {
            const response = await fetch('/api/auth/register', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    firstName: formData.firstName,
                    lastName: formData.lastName,
                    email: formData.email,
                    phone: `${formData.phoneCode}${formData.phone}`,
                    country: formData.country,
                    password: formData.password
                })
            });

            const data = await response.json();

            if (data.success) {
                // Save session
                localStorage.setItem('user', JSON.stringify(data.user));
                window.location.href = '/dashboard';
            } else {
                alert(data.message || 'Registration failed');
            }
        } catch (error) {
            console.error('Registration error:', error);
            alert('Registration failed. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    const passwordStrength = (password: string) => {
        if (password.length === 0) return { strength: 0, label: '' };
        if (password.length < 6) return { strength: 25, label: 'Weak', color: 'bg-red-500' };
        if (password.length < 10) return { strength: 50, label: 'Fair', color: 'bg-yellow-500' };
        if (password.length < 14) return { strength: 75, label: 'Good', color: 'bg-blue-500' };
        return { strength: 100, label: 'Strong', color: 'bg-accent-emerald' };
    };

    const strength = passwordStrength(formData.password);

    return (
        <main className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background-dark via-primary-950 to-background-dark relative overflow-hidden py-12">
            {/* Background Elements */}
            <div className="absolute top-0 right-0 w-96 h-96 bg-accent-gold/10 rounded-full blur-3xl" />
            <div className="absolute bottom-0 left-0 w-96 h-96 bg-accent-emerald/10 rounded-full blur-3xl" />

            <div className="section-container relative z-10">
                <div className="max-w-2xl mx-auto">
                    {/* Logo */}
                    <Link href="/" className="flex items-center justify-center space-x-2 mb-8">
                        {settings.siteLogo ? (
                            <img src={settings.siteLogo} alt={settings.siteName} className="h-12 w-auto object-contain" />
                        ) : (
                            <div className="w-12 h-12 bg-gradient-to-br from-accent-gold to-accent-gold-dark rounded-xl flex items-center justify-center">
                                <span className="text-primary-950 font-bold text-2xl font-serif">{settings.siteName.charAt(0)}</span>
                            </div>
                        )}
                        <span className="text-2xl font-serif font-bold gradient-text">
                            {settings.siteName}
                        </span>
                    </Link>

                    {/* Register Card */}
                    <div className="card-premium">
                        <div className="text-center mb-8">
                            <h1 className="text-3xl font-bold font-serif text-white mb-2">Create Your Account</h1>
                            <p className="text-gray-400">Start your investment journey today</p>
                        </div>

                        <form onSubmit={handleSubmit} className="space-y-6">
                            {/* Name Fields */}
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label htmlFor="firstName" className="block text-sm font-medium text-gray-300 mb-2">
                                        First Name
                                    </label>
                                    <div className="relative">
                                        <FiUser className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="firstName"
                                            name="firstName"
                                            type="text"
                                            value={formData.firstName}
                                            onChange={handleChange}
                                            placeholder="John"
                                            className="input-premium pl-12"
                                            required
                                        />
                                    </div>
                                </div>
                                <div>
                                    <label htmlFor="lastName" className="block text-sm font-medium text-gray-300 mb-2">
                                        Last Name
                                    </label>
                                    <div className="relative">
                                        <FiUser className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="lastName"
                                            name="lastName"
                                            type="text"
                                            value={formData.lastName}
                                            onChange={handleChange}
                                            placeholder="Doe"
                                            className="input-premium pl-12"
                                            required
                                        />
                                    </div>
                                </div>
                            </div>

                            {/* Email */}
                            <div>
                                <label htmlFor="email" className="block text-sm font-medium text-gray-300 mb-2">
                                    Email Address
                                </label>
                                <div className="relative">
                                    <FiMail className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="email"
                                        name="email"
                                        type="email"
                                        value={formData.email}
                                        onChange={handleChange}
                                        placeholder="you@example.com"
                                        className="input-premium pl-12"
                                        required
                                    />
                                </div>
                            </div>

                            {/* Country */}
                            <div>
                                <label htmlFor="country" className="block text-sm font-medium text-gray-300 mb-2">
                                    Country *
                                </label>
                                <div className="relative">
                                    <FiGlobe className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <select
                                        id="country"
                                        name="country"
                                        value={formData.country}
                                        onChange={handleCountryChange}
                                        className="input-premium pl-12 appearance-none cursor-pointer"
                                        required
                                    >
                                        <option value="">Select your country</option>
                                        {countries.map((country) => (
                                            <option key={country.code} value={country.name}>
                                                {country.name} ({country.phoneCode})
                                            </option>
                                        ))}
                                    </select>
                                </div>
                            </div>

                            {/* Phone */}
                            <div>
                                <label htmlFor="phone" className="block text-sm font-medium text-gray-300 mb-2">
                                    Phone Number <span className="text-gray-500">(Optional)</span>
                                </label>
                                <div className="flex space-x-2">
                                    <div className="relative w-32">
                                        <input
                                            type="text"
                                            value={formData.phoneCode}
                                            readOnly
                                            placeholder="Code"
                                            className="input-premium text-center bg-primary-800/50 cursor-not-allowed"
                                        />
                                    </div>
                                    <div className="relative flex-1">
                                        <FiPhone className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                        <input
                                            id="phone"
                                            name="phone"
                                            type="tel"
                                            value={formData.phone}
                                            onChange={handleChange}
                                            placeholder="123-4567"
                                            className="input-premium pl-12"
                                            disabled={!formData.country}
                                        />
                                    </div>
                                </div>
                                {!formData.country && (
                                    <p className="mt-1 text-xs text-gray-500">Please select a country first</p>
                                )}
                            </div>

                            {/* Password */}
                            <div>
                                <label htmlFor="password" className="block text-sm font-medium text-gray-300 mb-2">
                                    Password
                                </label>
                                <div className="relative">
                                    <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="password"
                                        name="password"
                                        type={showPassword ? 'text' : 'password'}
                                        value={formData.password}
                                        onChange={handleChange}
                                        placeholder="••••••••"
                                        className="input-premium pl-12 pr-12"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                    >
                                        {showPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                    </button>
                                </div>
                                {formData.password && (
                                    <div className="mt-2">
                                        <div className="flex items-center justify-between mb-1">
                                            <span className="text-xs text-gray-400">Password strength</span>
                                            <span className={`text-xs font-semibold ${strength.strength >= 75 ? 'text-accent-emerald' : strength.strength >= 50 ? 'text-yellow-400' : 'text-red-400'}`}>
                                                {strength.label}
                                            </span>
                                        </div>
                                        <div className="progress-bar h-1">
                                            <div className={`h-full rounded-full transition-all duration-300 ${strength.color}`} style={{ width: `${strength.strength}%` }} />
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Confirm Password */}
                            <div>
                                <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-300 mb-2">
                                    Confirm Password
                                </label>
                                <div className="relative">
                                    <FiLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
                                    <input
                                        id="confirmPassword"
                                        name="confirmPassword"
                                        type={showConfirmPassword ? 'text' : 'password'}
                                        value={formData.confirmPassword}
                                        onChange={handleChange}
                                        placeholder="••••••••"
                                        className="input-premium pl-12 pr-12"
                                        required
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                                        className="absolute right-4 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-accent-gold transition-colors"
                                    >
                                        {showConfirmPassword ? <FiEyeOff className="w-5 h-5" /> : <FiEye className="w-5 h-5" />}
                                    </button>
                                </div>
                                {formData.confirmPassword && formData.password !== formData.confirmPassword && (
                                    <p className="mt-1 text-xs text-red-400">Passwords do not match</p>
                                )}
                            </div>

                            {/* Terms Agreement */}
                            <div className="flex items-start space-x-3">
                                <input
                                    id="terms"
                                    type="checkbox"
                                    checked={agreedToTerms}
                                    onChange={(e) => setAgreedToTerms(e.target.checked)}
                                    className="w-5 h-5 mt-0.5 rounded border-primary-700 bg-primary-800 text-accent-gold focus:ring-accent-gold/50"
                                    required
                                />
                                <label htmlFor="terms" className="text-sm text-gray-400">
                                    I agree to the{' '}
                                    <Link href="/terms" className="text-accent-gold hover:text-accent-gold-light">
                                        Terms & Conditions
                                    </Link>{' '}
                                    and{' '}
                                    <Link href="/privacy" className="text-accent-gold hover:text-accent-gold-light">
                                        Privacy Policy
                                    </Link>
                                </label>
                            </div>

                            {/* Submit Button */}
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="btn-primary w-full text-lg disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                {isLoading ? 'Creating Account...' : 'Create Account'}
                            </button>
                        </form>

                        {/* Divider */}
                        <div className="relative my-8">
                            <div className="divider" />
                            <span className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-background-dark-secondary px-4 text-sm text-gray-400">
                                or
                            </span>
                        </div>

                        {/* Sign In Link */}
                        <p className="text-center text-gray-400">
                            Already have an account?{' '}
                            <Link href="/login" className="text-accent-gold hover:text-accent-gold-light font-semibold transition-colors">
                                Sign In
                            </Link>
                        </p>

                        {/* Trust Indicators */}
                        <div className="mt-8 pt-6 border-t border-primary-700/30">
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-center">
                                <div className="flex flex-col items-center space-y-2">
                                    <FiShield className="w-5 h-5 text-accent-emerald" />
                                    <span className="text-xs text-gray-400">Secure Registration</span>
                                </div>
                                <div className="flex flex-col items-center space-y-2">
                                    <FiCheckCircle className="w-5 h-5 text-accent-emerald" />
                                    <span className="text-xs text-gray-400">Instant Verification</span>
                                </div>
                                <div className="flex flex-col items-center space-y-2">
                                    <FiLock className="w-5 h-5 text-accent-emerald" />
                                    <span className="text-xs text-gray-400">Data Protected</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Back to Home */}
                    <div className="text-center mt-6">
                        <Link href="/" className="text-gray-400 hover:text-accent-gold transition-colors text-sm">
                            ← Back to Home
                        </Link>
                    </div>
                </div>
            </div>
        </main>
    );
}

'use client';

import { useState, useRef, useEffect } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { FiMenu, FiBell, FiChevronDown, FiUser, FiLogOut, FiSettings, FiCheck, FiInfo, FiDollarSign, FiShield } from 'react-icons/fi';
import { useSiteSettings } from '@/context/SiteContext';

interface AdminHeaderProps {
    user: any;
    onMenuClick: () => void;
}

interface Notification {
    _id: string;
    type: 'deposit' | 'withdrawal' | 'kyc' | 'registration';
    title: string;
    message: string;
    isRead: boolean;
    createdAt: string;
}

export default function AdminHeader({ user, onMenuClick }: AdminHeaderProps) {
    const { settings } = useSiteSettings();
    const router = useRouter();
    const siteName = settings.siteName;
    const [dropdownOpen, setDropdownOpen] = useState(false);
    const [notifDropdownOpen, setNotifDropdownOpen] = useState(false);
    const [notifications, setNotifications] = useState<Notification[]>([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [loading, setLoading] = useState(false);
    const [page, setPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);

    const dropdownRef = useRef<HTMLDivElement>(null);
    const notifRef = useRef<HTMLDivElement>(null);

    // Close dropdowns when clicking outside
    useEffect(() => {
        function handleClickOutside(event: MouseEvent) {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setDropdownOpen(false);
            }
            if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
                setNotifDropdownOpen(false);
            }
        }
        document.addEventListener("mousedown", handleClickOutside);
        return () => {
            document.removeEventListener("mousedown", handleClickOutside);
        };
    }, []);

    const fetchNotifications = async (isLoadMore = false) => {
        if (loading) return;
        setLoading(true);
        try {
            // If refreshing (page 1), reset
            const currentPage = isLoadMore ? page + 1 : 1;

            const res = await fetch(`/api/admin/notifications?page=${currentPage}&limit=5`);
            const data = await res.json();

            if (data.success) {
                if (isLoadMore) {
                    setNotifications(prev => [...prev, ...data.notifications]);
                    setPage(currentPage);
                } else {
                    setNotifications(data.notifications);
                    setPage(1);
                }
                setUnreadCount(data.unreadCount);
                setHasMore(data.pagination.page < data.pagination.pages);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        // Initial fetch
        fetchNotifications();

        // Poll every 30 seconds
        const interval = setInterval(() => fetchNotifications(), 30000);
        return () => clearInterval(interval);
    }, []);

    const handleMarkAsRead = async (id?: string) => {
        try {
            if (id) {
                // Optimistic update
                setNotifications(prev => prev.map(n => n._id === id ? { ...n, isRead: true } : n));
                setUnreadCount(prev => Math.max(0, prev - 1));

                await fetch('/api/admin/notifications', {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ id })
                });
            } else {
                // Mark all
                setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
                setUnreadCount(0);
                await fetch('/api/admin/notifications', {
                    method: 'PATCH',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ type: 'markAllRead' })
                });
            }
        } catch (error) {
            console.error(error);
        }
    };

    const handleNotificationClick = (notif: Notification) => {
        if (!notif.isRead) handleMarkAsRead(notif._id);
        setNotifDropdownOpen(false);

        // Routing logic based on type
        switch (notif.type) {
            case 'deposit': router.push('/admin/deposits'); break;
            case 'withdrawal': router.push('/admin/withdrawals'); break;
            case 'kyc': router.push('/admin/kyc'); break;
            case 'registration': router.push('/admin/users'); break;
            default: break;
        }
    };

    const getIcon = (type: string) => {
        switch (type) {
            case 'deposit': return <FiDollarSign className="text-green-400" />;
            case 'withdrawal': return <FiDollarSign className="text-red-400" />;
            case 'kyc': return <FiShield className="text-blue-400" />;
            default: return <FiUser className="text-accent-gold" />;
        }
    };

    const handleLogout = () => {
        localStorage.removeItem('user');
        window.location.href = '/login';
    };

    return (
        <header className="fixed top-0 right-0 left-0 lg:left-64 h-16 bg-primary-900/95 backdrop-blur-md border-b border-primary-800 z-30 transition-all duration-300">
            <div className="h-full px-4 sm:px-6 flex items-center justify-between">
                {/* Left: Mobile Menu & Brand (Mobile only) */}
                <div className="flex items-center gap-3">
                    <button
                        onClick={onMenuClick}
                        className="lg:hidden p-2 text-gray-300 hover:text-white hover:bg-primary-800 rounded-lg transition-colors"
                    >
                        <FiMenu size={24} />
                    </button>
                    {/* Mobile Brand */}
                    <span className="lg:hidden text-lg font-bold font-serif text-white tracking-wider">
                        {siteName}
                    </span>
                </div>

                {/* Right: Actions & Profile */}
                <div className="flex items-center gap-4 ml-auto">
                    {/* Notifications */}
                    <div className="relative" ref={notifRef}>
                        <button
                            onClick={() => { setNotifDropdownOpen(!notifDropdownOpen); if (!notifDropdownOpen) fetchNotifications(); }}
                            className="p-2 text-gray-400 hover:text-white relative hover:bg-white/5 rounded-full transition-colors"
                        >
                            <FiBell size={20} />
                            {unreadCount > 0 && (
                                <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full animate-pulse shadow-lg shadow-red-500/50"></span>
                            )}
                        </button>

                        {/* Notifications Dropdown */}
                        {notifDropdownOpen && (
                            <div className="absolute right-0 top-full mt-2 w-80 md:w-96 bg-primary-900 border border-primary-700 rounded-xl shadow-xl overflow-hidden animate-scale-in origin-top-right z-50">
                                <div className="p-4 border-b border-primary-800 flex justify-between items-center bg-primary-800/20">
                                    <h3 className="font-bold text-white">Notifications</h3>
                                    {unreadCount > 0 && (
                                        <button onClick={() => handleMarkAsRead()} className="text-xs text-accent-gold hover:text-white transition-colors">
                                            Mark all as read
                                        </button>
                                    )}
                                </div>
                                <div className="max-h-[60vh] overflow-y-auto">
                                    {notifications.length === 0 ? (
                                        <div className="p-8 text-center text-gray-500">
                                            <FiBell className="mx-auto w-8 h-8 mb-2 opacity-50" />
                                            <p>No notifications yet</p>
                                        </div>
                                    ) : (
                                        <div className="divide-y divide-primary-800">
                                            {notifications.map(notif => (
                                                <div
                                                    key={notif._id}
                                                    onClick={() => handleNotificationClick(notif)}
                                                    className={`p-4 hover:bg-primary-800/50 transition-colors cursor-pointer flex gap-3 ${!notif.isRead ? 'bg-primary-800/10 border-l-2 border-accent-gold' : ''}`}
                                                >
                                                    <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 bg-primary-800`}>
                                                        {getIcon(notif.type)}
                                                    </div>
                                                    <div className="flex-1 min-w-0">
                                                        <p className={`text-sm ${!notif.isRead ? 'font-semibold text-white' : 'text-gray-300'}`}>
                                                            {notif.title}
                                                        </p>
                                                        <p className="text-xs text-gray-400 truncate mt-0.5">{notif.message}</p>
                                                        <p className="text-[10px] text-gray-500 mt-1">{new Date(notif.createdAt).toLocaleString()}</p>
                                                    </div>
                                                </div>
                                            ))}
                                            {hasMore && (
                                                <button
                                                    onClick={(e) => { e.stopPropagation(); fetchNotifications(true); }}
                                                    className="w-full py-3 text-xs text-center text-gray-400 hover:text-white hover:bg-primary-800 transition-colors"
                                                    disabled={loading}
                                                >
                                                    {loading ? 'Loading...' : 'Load more'}
                                                </button>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </div>

                    {/* Profile Dropdown */}
                    <div className="relative" ref={dropdownRef}>
                        <button
                            onClick={() => setDropdownOpen(!dropdownOpen)}
                            className="flex items-center gap-3 p-1.5 rounded-lg hover:bg-primary-800 transition-colors"
                        >
                            <div className="w-8 h-8 rounded-full bg-gradient-to-br from-accent-gold to-yellow-600 flex items-center justify-center text-primary-950 font-bold text-sm">
                                {user?.firstName?.charAt(0) || 'A'}
                            </div>
                            <span className="hidden md:block text-sm font-medium text-white">
                                {user?.firstName} {user?.lastName}
                            </span>
                            <FiChevronDown className={`text-gray-400 transition-transform ${dropdownOpen ? 'rotate-180' : ''}`} />
                        </button>

                        {/* Dropdown Menu */}
                        {dropdownOpen && (
                            <div className="absolute right-0 top-full mt-2 w-48 bg-primary-900 border border-primary-700 rounded-xl shadow-xl overflow-hidden animate-scale-in origin-top-right">
                                <div className="p-3 border-b border-primary-800 md:hidden">
                                    <p className="text-sm font-bold text-white">{user?.firstName} {user?.lastName}</p>
                                    <p className="text-xs text-gray-400 truncate">{user?.email}</p>
                                </div>
                                <div className="py-1">
                                    <Link
                                        href="/admin/profile"
                                        onClick={() => setDropdownOpen(false)}
                                        className="flex items-center gap-3 px-4 py-3 text-sm text-gray-300 hover:bg-primary-800 hover:text-white transition-colors"
                                    >
                                        <FiUser size={16} /> Profile Settings
                                    </Link>
                                    <button
                                        onClick={handleLogout}
                                        className="w-full flex items-center gap-3 px-4 py-3 text-sm text-red-400 hover:bg-red-500/10 hover:text-red-300 transition-colors text-left"
                                    >
                                        <FiLogOut size={16} /> Logout
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </header>
    );
}

'use client';

import Link from 'next/link';
import { useState, useEffect, useRef } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { useSiteSettings } from '@/context/SiteContext';
import { FiMenu, FiX, FiUser, FiLogOut, FiArrowLeft, FiSettings, FiHelpCircle, FiGrid, FiChevronDown, FiBell, FiDollarSign, FiTrendingUp, FiShield } from 'react-icons/fi';

interface NavbarProps {
    isAuthenticated?: boolean;
    isAdmin?: boolean;
    user?: {
        _id?: string;
        firstName: string;
        lastName: string;
        email?: string;
    } | null;
}

export default function Navbar({ isAuthenticated: propIsAuthenticated, isAdmin: propIsAdmin, user: propUser }: NavbarProps) {
    const { settings } = useSiteSettings();
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [profileDropdownOpen, setProfileDropdownOpen] = useState(false);

    // Internal Auth State (to handle client-side checks on public pages)
    const [isLoggedIn, setIsLoggedIn] = useState(!!propIsAuthenticated);
    const [currentUser, setCurrentUser] = useState(propUser || null);
    const [isAdminState, setIsAdminState] = useState(!!propIsAdmin);

    // Sync propUser with state
    useEffect(() => {
        if (propUser) setCurrentUser(propUser);
    }, [propUser]);

    const pathname = usePathname();
    const router = useRouter();
    const dropdownRef = useRef<HTMLDivElement>(null);
    const notifRef = useRef<HTMLDivElement>(null);

    // Notification State
    const [notifDropdownOpen, setNotifDropdownOpen] = useState(false);
    const [notifications, setNotifications] = useState<any[]>([]);
    const [unreadCount, setUnreadCount] = useState(0);
    const [loading, setLoading] = useState(false);
    const [page, setPage] = useState(1);
    const [hasMore, setHasMore] = useState(true);

    // Fetch Notifications
    const fetchNotifications = async (isLoadMore = false) => {
        if (!currentUser?._id || loading) return;
        setLoading(true);
        try {
            const currentPage = isLoadMore ? page + 1 : 1;
            const res = await fetch(`/api/user/notifications?userId=${currentUser._id}&page=${currentPage}&limit=5`);
            const data = await res.json();

            if (data.success) {
                if (isLoadMore) {
                    setNotifications(prev => [...prev, ...data.notifications]);
                    setPage(currentPage);
                } else {
                    setNotifications(data.notifications);
                    setPage(1);
                }
                setUnreadCount(data.unreadCount);
                setHasMore(data.pagination.page < data.pagination.pages);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setLoading(false);
        }
    };

    // Mark as Read
    const handleMarkAsRead = async (id?: string) => {
        if (!currentUser?._id) return;
        try {
            if (id) {
                setNotifications(prev => prev.map(n => n._id === id ? { ...n, isRead: true } : n));
                setUnreadCount(prev => Math.max(0, prev - 1));
                await fetch('/api/user/notifications', { method: 'PATCH', body: JSON.stringify({ id, userId: currentUser._id }) });
            } else {
                setNotifications(prev => prev.map(n => ({ ...n, isRead: true })));
                setUnreadCount(0);
                await fetch('/api/user/notifications', { method: 'PATCH', body: JSON.stringify({ type: 'markAllRead', userId: currentUser._id }) });
            }
        } catch (error) {
            console.error(error);
        }
    };

    useEffect(() => {
        if (currentUser?._id) {
            fetchNotifications();
            const interval = setInterval(() => fetchNotifications(), 10000); // Poll every 10s
            return () => clearInterval(interval);
        }
    }, [currentUser?._id]);

    // Close on click outside
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setProfileDropdownOpen(false);
            }
            if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
                setNotifDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    const handleLogout = () => {
        localStorage.removeItem('user');
        localStorage.removeItem('token');
        setIsLoggedIn(false);
        setCurrentUser(null);
        setProfileDropdownOpen(false);
        router.push('/login');
    };

    const navLinks = [
        { href: '/', label: 'Home' },
        { href: '/plans', label: 'Investment Plans' },
        { href: '/about', label: 'About' },
        { href: '/contact', label: 'Contact' },
    ];

    // Show Back Button if logged in and NOT on the main dashboard or home
    const showBackButton = isLoggedIn && pathname !== '/dashboard' && pathname !== '/';

    return (
        <nav className="fixed top-0 left-0 right-0 z-50 bg-background-dark/80 backdrop-blur-xl border-b border-primary-800/50">
            <div className="section-container">
                <div className="flex items-center justify-between h-20">

                    {/* Left Section: Back Button + Logo */}
                    <div className="flex items-center gap-4">
                        {showBackButton && (
                            <Link
                                href="/dashboard"
                                className="p-2 -ml-2 text-gray-300 hover:text-accent-gold transition-colors duration-200 rounded-full hover:bg-white/5"
                                aria-label="Back to Dashboard"
                            >
                                <FiArrowLeft className="w-6 h-6" />
                            </Link>
                        )}

                        {/* Logo */}
                        <Link href="/" className="flex items-center space-x-2 group">
                            {settings.siteLogo ? (
                                <img src={settings.siteLogo} alt={settings.siteName} className="h-10 w-auto object-contain" />
                            ) : (
                                <div className="flex items-center space-x-2">
                                    <div className="w-10 h-10 bg-gradient-to-br from-accent-gold to-accent-gold-dark rounded-lg flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
                                        <span className="text-primary-950 font-bold text-xl font-serif">{settings.siteName.charAt(0)}</span>
                                    </div>
                                    <span className="text-xl font-serif font-bold gradient-text hidden sm:block">
                                        {settings.siteName}
                                    </span>
                                </div>
                            )}
                        </Link>
                    </div>

                    {/* Desktop Navigation */}
                    <div className="hidden md:flex items-center space-x-8">
                        {navLinks.map((link) => (
                            <Link
                                key={link.href}
                                href={link.href}
                                className={`transition-colors duration-200 font-medium ${pathname === link.href ? 'text-accent-gold' : 'text-gray-300 hover:text-accent-gold'
                                    }`}
                            >
                                {link.label}
                            </Link>
                        ))}
                    </div>

                    {/* Desktop Auth Buttons / User Profile */}
                    <div className="hidden md:flex items-center space-x-4">
                        {isLoggedIn ? (
                            <>
                                {/* User Notifications */}
                                <div className="relative" ref={notifRef}>
                                    <button
                                        onClick={() => { setNotifDropdownOpen(!notifDropdownOpen); if (!notifDropdownOpen) fetchNotifications(); }}
                                        className="p-2 text-gray-300 hover:text-accent-gold relative transition-colors"
                                    >
                                        <FiBell className="w-6 h-6" />
                                        {unreadCount > 0 && (
                                            <span className="absolute top-1 right-1 w-2.5 h-2.5 bg-red-500 rounded-full animate-pulse border border-background-dark"></span>
                                        )}
                                    </button>

                                    {/* Notifications Dropdown */}
                                    {notifDropdownOpen && (
                                        <div className="absolute right-0 top-full mt-4 w-80 md:w-96 bg-primary-900 border border-primary-700/50 rounded-xl shadow-xl shadow-black/50 overflow-hidden animate-slide-up origin-top-right z-50">
                                            <div className="p-4 border-b border-primary-800 flex justify-between items-center bg-primary-800/20">
                                                <h3 className="font-bold text-white font-serif">Notifications</h3>
                                                {unreadCount > 0 && (
                                                    <button onClick={() => handleMarkAsRead()} className="text-xs text-accent-gold hover:text-white transition-colors font-medium">
                                                        Mark all as read
                                                    </button>
                                                )}
                                            </div>
                                            <div className="max-h-[60vh] overflow-y-auto custom-scrollbar">
                                                {notifications.length === 0 ? (
                                                    <div className="p-8 text-center text-gray-500">
                                                        <FiBell className="mx-auto w-8 h-8 mb-3 opacity-30" />
                                                        <p>No notifications yet</p>
                                                    </div>
                                                ) : (
                                                    <div className="divide-y divide-primary-800/50">
                                                        {notifications.map(notif => (
                                                            <div
                                                                key={notif._id}
                                                                onClick={() => !notif.isRead && handleMarkAsRead(notif._id)}
                                                                className={`p-4 hover:bg-primary-800/30 transition-colors flex gap-3 ${!notif.isRead ? 'bg-primary-800/10' : ''}`}
                                                            >
                                                                <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 ${notif.type === 'deposit' ? 'bg-green-500/20 text-green-500' :
                                                                    notif.type === 'withdrawal' ? 'bg-red-500/20 text-red-500' :
                                                                        notif.type === 'kyc' ? 'bg-blue-500/20 text-blue-500' :
                                                                            notif.type === 'investment' ? 'bg-accent-gold/20 text-accent-gold' :
                                                                                'bg-gray-700/50 text-gray-400'
                                                                    }`}>
                                                                    {notif.type === 'deposit' ? <FiDollarSign /> :
                                                                        notif.type === 'withdrawal' ? <FiDollarSign /> :
                                                                            notif.type === 'kyc' ? <FiShield /> :
                                                                                notif.type === 'investment' ? <FiTrendingUp /> : <FiBell />}
                                                                </div>
                                                                <div className="flex-1 min-w-0">
                                                                    <div className="flex justify-between items-start mb-0.5">
                                                                        <p className={`text-sm ${!notif.isRead ? 'font-bold text-white' : 'text-gray-300 font-medium'}`}>
                                                                            {notif.title}
                                                                        </p>
                                                                        {!notif.isRead && (
                                                                            <span className="w-2 h-2 bg-accent-gold rounded-full flex-shrink-0 mt-1.5 ml-2"></span>
                                                                        )}
                                                                    </div>
                                                                    <p className="text-xs text-gray-400 leading-relaxed">{notif.message}</p>
                                                                    <p className="text-[10px] text-gray-500 mt-2 font-medium">
                                                                        {new Date(notif.createdAt).toLocaleDateString()} • {new Date(notif.createdAt).toLocaleTimeString()}
                                                                    </p>
                                                                </div>
                                                            </div>
                                                        ))}
                                                        {hasMore && (
                                                            <button
                                                                onClick={(e) => { e.stopPropagation(); fetchNotifications(true); }}
                                                                className="w-full py-3 text-xs font-medium text-center text-gray-400 hover:text-white hover:bg-primary-800/30 transition-colors"
                                                                disabled={loading}
                                                            >
                                                                {loading ? 'Loading...' : 'Load more'}
                                                            </button>
                                                        )}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    )}
                                </div>

                                <div className="relative" ref={dropdownRef}>
                                    <button
                                        onClick={() => setProfileDropdownOpen(!profileDropdownOpen)}
                                        className="flex items-center space-x-2 text-gray-300 hover:text-accent-gold transition-colors duration-200 focus:outline-none"
                                    >
                                        <div className="w-8 h-8 rounded-full bg-primary-800 flex items-center justify-center border border-primary-700">
                                            <FiUser className="w-4 h-4" />
                                        </div>
                                        <span className="font-medium">
                                            {currentUser ? `${currentUser.firstName} ${currentUser.lastName}` : 'Account'}
                                        </span>
                                        <FiChevronDown className={`w-4 h-4 transition-transform ${profileDropdownOpen ? 'rotate-180' : ''}`} />
                                    </button>

                                    {/* Dropdown Menu */}
                                    {profileDropdownOpen && (
                                        <div className="absolute right-0 mt-3 w-56 bg-primary-900 border border-primary-700/50 rounded-xl shadow-xl shadow-black/50 overflow-hidden animate-slide-up origin-top-right">
                                            {/* ... content ... */}
                                            <div className="px-4 py-3 border-b border-primary-800/50">
                                                <p className="text-sm text-gray-400">Signed in as</p>
                                                <p className="text-sm font-bold text-white truncate">{currentUser?.email}</p>
                                            </div>
                                            <div className="py-1">
                                                <Link
                                                    href={isAdminState ? '/admin' : '/dashboard'}
                                                    className="flex items-center px-4 py-2.5 text-sm text-gray-300 hover:bg-primary-800 hover:text-accent-gold transition-colors"
                                                    onClick={() => setProfileDropdownOpen(false)}
                                                >
                                                    <FiGrid className="mr-3 w-4 h-4" />
                                                    Dashboard
                                                </Link>
                                                <Link
                                                    href="/dashboard/settings"
                                                    className="flex items-center px-4 py-2.5 text-sm text-gray-300 hover:bg-primary-800 hover:text-accent-gold transition-colors"
                                                    onClick={() => setProfileDropdownOpen(false)}
                                                >
                                                    <FiSettings className="mr-3 w-4 h-4" />
                                                    Profile Settings
                                                </Link>
                                                <Link
                                                    href="/contact"
                                                    className="flex items-center px-4 py-2.5 text-sm text-gray-300 hover:bg-primary-800 hover:text-accent-gold transition-colors"
                                                    onClick={() => setProfileDropdownOpen(false)}
                                                >
                                                    <FiHelpCircle className="mr-3 w-4 h-4" />
                                                    Support
                                                </Link>
                                            </div>
                                            <div className="border-t border-primary-800/50 py-1">
                                                <button
                                                    onClick={handleLogout}
                                                    className="flex w-full items-center px-4 py-2.5 text-sm text-red-400 hover:bg-red-500/10 transition-colors"
                                                >
                                                    <FiLogOut className="mr-3 w-4 h-4" />
                                                    Logout
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </>
                        ) : (
                            <>
                                <Link href="/login" className="btn-secondary">
                                    Login
                                </Link>
                                <Link href="/register" className="btn-primary">
                                    Get Started
                                </Link>
                            </>
                        )}
                    </div>

                    {/* Mobile Profile & Menu */}
                    <div className="flex items-center gap-2 md:hidden">
                        {isLoggedIn && (
                            <div className="relative" ref={dropdownRef}>
                                <button
                                    onClick={() => setProfileDropdownOpen(!profileDropdownOpen)}
                                    className="w-9 h-9 rounded-full bg-gradient-to-br from-accent-gold to-accent-gold-dark flex items-center justify-center text-primary-950 font-bold shadow-lg"
                                >
                                    {currentUser?.firstName?.charAt(0) || <FiUser />}
                                </button>

                                {/* Mobile Profile Dropdown */}
                                {profileDropdownOpen && (
                                    <div className="absolute right-0 top-full mt-3 w-64 bg-primary-900 border border-primary-700/50 rounded-xl shadow-xl shadow-black/50 overflow-hidden animate-slide-up origin-top-right z-50">
                                        <div className="px-4 py-4 bg-primary-800/30 border-b border-primary-700/50">
                                            <div className="flex items-center gap-3 mb-2">
                                                <div className="w-10 h-10 rounded-full bg-accent-gold/20 flex items-center justify-center text-accent-gold">
                                                    <span className="font-bold text-lg">{currentUser?.firstName?.charAt(0)}</span>
                                                </div>
                                                <div className="overflow-hidden">
                                                    <p className="font-bold text-white truncate">{currentUser?.firstName} {currentUser?.lastName}</p>
                                                    <p className="text-xs text-gray-400 truncate">{currentUser?.email}</p>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="p-2 space-y-1">
                                            <Link
                                                href={isAdminState ? '/admin' : '/dashboard'}
                                                className="flex items-center px-4 py-3 text-sm font-medium text-gray-300 hover:bg-primary-800 hover:text-white rounded-lg transition-colors"
                                                onClick={() => setProfileDropdownOpen(false)}
                                            >
                                                <FiGrid className="mr-3 w-4 h-4 text-accent-gold" />
                                                Dashboard
                                            </Link>
                                            <Link
                                                href="/dashboard/settings"
                                                className="flex items-center px-4 py-3 text-sm font-medium text-gray-300 hover:bg-primary-800 hover:text-white rounded-lg transition-colors"
                                                onClick={() => setProfileDropdownOpen(false)}
                                            >
                                                <FiSettings className="mr-3 w-4 h-4 text-accent-gold" />
                                                Profile Settings
                                            </Link>
                                            <Link
                                                href="/contact"
                                                className="flex items-center px-4 py-3 text-sm font-medium text-gray-300 hover:bg-primary-800 hover:text-white rounded-lg transition-colors"
                                                onClick={() => setProfileDropdownOpen(false)}
                                            >
                                                <FiHelpCircle className="mr-3 w-4 h-4 text-accent-gold" />
                                                Support
                                            </Link>
                                            <div className="border-t border-primary-800/50 my-1"></div>
                                            <button
                                                onClick={() => { setProfileDropdownOpen(false); handleLogout(); }}
                                                className="flex w-full items-center px-4 py-3 text-sm font-medium text-red-400 hover:bg-red-500/10 rounded-lg transition-colors"
                                            >
                                                <FiLogOut className="mr-3 w-4 h-4" />
                                                Logout
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Mobile Menu Button */}
                        <button
                            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
                            className="p-2 text-gray-300 hover:text-accent-gold transition-colors duration-200"
                        >
                            {mobileMenuOpen ? <FiX className="w-6 h-6" /> : <FiMenu className="w-6 h-6" />}
                        </button>
                    </div>
                </div>

                {/* Mobile Menu */}
                {mobileMenuOpen && (
                    <div className="md:hidden py-4 border-t border-primary-800/50 animate-slide-down bg-background-dark/95 backdrop-blur-xl absolute left-0 right-0 px-4 shadow-2xl h-screen">
                        <div className="flex flex-col space-y-4">
                            {navLinks.map((link) => (
                                <Link
                                    key={link.href}
                                    href={link.href}
                                    className={`font-medium py-3 px-4 rounded-lg transition-colors duration-200 ${pathname === link.href ? 'bg-primary-800/50 text-accent-gold' : 'text-gray-300 hover:bg-white/5 hover:text-accent-gold'
                                        }`}
                                    onClick={() => setMobileMenuOpen(false)}
                                >
                                    {link.label}
                                </Link>
                            ))}

                            {!isLoggedIn && (
                                <div className="grid grid-cols-2 gap-4 mt-4 pt-4 border-t border-primary-800/50">
                                    <Link href="/login" className="btn-secondary w-full text-center justify-center p-3" onClick={() => setMobileMenuOpen(false)}>
                                        Login
                                    </Link>
                                    <Link href="/register" className="btn-primary w-full text-center justify-center p-3" onClick={() => setMobileMenuOpen(false)}>
                                        Get Started
                                    </Link>
                                </div>
                            )}
                        </div>
                    </div>
                )}
            </div>
        </nav>
    );
}

'use client';

import { useEffect, useRef, memo } from 'react';

// 1. Ticker Tape Widget (Scrolling Top Bar)
export const TickerTape = memo(() => {
    const container = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!container.current) return;
        const script = document.createElement("script");
        script.src = "https://s3.tradingview.com/external-embedding/embed-widget-ticker-tape.js";
        script.type = "text/javascript";
        script.async = true;
        script.innerHTML = JSON.stringify({
            "symbols": [
                { "proName": "FOREXCOM:SPXUSD", "title": "S&P 500" },
                { "proName": "FOREXCOM:NSXUSD", "title": "US 100" },
                { "proName": "FX_IDC:EURUSD", "title": "EUR/USD" },
                { "proName": "BITSTAMP:BTCUSD", "title": "Bitcoin" },
                { "proName": "BITSTAMP:ETHUSD", "title": "Ethereum" },
                { "proName": "BINANCE:SOLUSDT", "title": "Solana" },
                { "proName": "BINANCE:BNBUSDT", "title": "BNB" },
                { "proName": "BINANCE:XRPUSDT", "title": "XRP" }
            ],
            "showSymbolLogo": true,
            "colorTheme": "dark",
            "isTransparent": false,
            "displayMode": "adaptive",
            "locale": "en"
        });
        container.current.innerHTML = '';
        container.current.appendChild(script);
    }, []);

    return <div className="tradingview-widget-container" ref={container}><div className="tradingview-widget-container__widget"></div></div>;
});
TickerTape.displayName = 'TickerTape';

